INSERT INTO messages (id, chat_id, sender_id, content, sent_at) VALUES
-- Randonnée Lac Blanc
('e0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001', 'Bienvenue dans le groupe ! RDV au départ du téléphérique à 9h pétantes.', '2026-03-02 10:00:00'),
('e0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002', 'Parfait, on prend quoi comme équipement ?', '2026-03-02 10:30:00'),
('e0000000-0000-4000-8000-000000000003', 'd0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001', 'Chaussures de rando impératives, gants et coupe-vent. Je fournis les bâtons.', '2026-03-02 11:00:00'),
-- Tour Vieux Lyon
('e0000000-0000-4000-8000-000000000004', 'd0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000006', 'Bonjour à tous ! On se retrouve place Saint-Jean à 10h. Prévoyez des chaussures confortables.', '2026-03-03 09:00:00'),
('e0000000-0000-4000-8000-000000000005', 'd0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000005', 'Super, j''ai hâte de découvrir les traboules !', '2026-03-03 09:15:00'),
('e0000000-0000-4000-8000-000000000006', 'd0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000008', 'Est-ce qu''il y a un restaurant prévu après la visite ?', '2026-03-03 10:00:00'),
('e0000000-0000-4000-8000-000000000007', 'd0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000006', 'Bonne idée ! Je connais un bouchon lyonnais parfait, je réserve pour après.', '2026-03-03 10:30:00'),
-- Escalade Fontainebleau
('e0000000-0000-4000-8000-000000000008', 'd0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000013', 'Salut l''équipe ! Niveau intermédiaire requis. Le matériel est fourni.', '2026-03-06 08:00:00'),
('e0000000-0000-4000-8000-000000000009', 'd0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000011', 'Nickel. On covoiture depuis Paris ?', '2026-03-06 08:30:00'),
('e0000000-0000-4000-8000-000000000010', 'd0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000007', 'Je peux prendre 2 personnes depuis la Gare de Lyon !', '2026-03-06 09:00:00'),
-- Kayak Lac d'Annecy
('e0000000-0000-4000-8000-000000000011', 'd0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000006', 'Bienvenue ! RDV à la base nautique de Talloires à 13h. Prévoir maillot de bain.', '2026-03-16 10:00:00'),
('e0000000-0000-4000-8000-000000000012', 'd0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000003', 'L''eau est froide en mai ?', '2026-03-16 10:30:00'),
('e0000000-0000-4000-8000-000000000013', 'd0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000006', 'Autour de 16°C, les combinaisons sont disponibles sur place.', '2026-03-16 11:00:00'),
-- Marché Provençal
('e0000000-0000-4000-8000-000000000014', 'd0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000012', 'Coucou ! On se retrouve à l''entrée du marché Aix à 10h. Venez l''estomac vide !', '2026-03-19 09:00:00'),
('e0000000-0000-4000-8000-000000000015', 'd0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000008', 'Trop impatiente, j''adore cuisiner !', '2026-03-19 09:30:00'),
('e0000000-0000-4000-8000-000000000016', 'd0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000009', 'On fait quoi comme plat exactement ?', '2026-03-19 10:00:00'),
('e0000000-0000-4000-8000-000000000017', 'd0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000012', 'Tapenade, ratatouille et tarte aux figues. De vrais classiques provençaux !', '2026-03-19 10:15:00'),
-- Trek Mont-Blanc
('e0000000-0000-4000-8000-000000000018', 'd0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000013', 'Bonsoir à tous ! Rappel : ce trek est exigeant. Assurez-vous d''être en bonne forme physique.', '2026-03-21 19:00:00'),
('e0000000-0000-4000-8000-000000000019', 'd0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000010', 'Compris ! On dort dans quels refuges ?', '2026-03-21 19:30:00'),
('e0000000-0000-4000-8000-000000000020', 'd0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000013', 'Refuge du Lac Blanc J1, Refuge de la Charpoua J2. J''enverrai la liste de matériel ce soir.', '2026-03-21 20:00:00'),
('e0000000-0000-4000-8000-000000000021', 'd0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000002', 'Super organisé, merci Olivier !', '2026-03-21 20:15:00'),
-- Calanques
('e0000000-0000-4000-8000-000000000022', 'd0000000-0000-4000-8000-000000000009', 'a0000000-0000-4000-8000-000000000014', 'Salut ! Prêts pour les Calanques le 12 ?', '2026-03-31 10:00:00'),
('e0000000-0000-4000-8000-000000000023', 'd0000000-0000-4000-8000-000000000009', 'a0000000-0000-4000-8000-000000000015', 'Carrément hâte ! On se voit là-bas.', '2026-03-31 10:15:00'),
('e0000000-0000-4000-8000-000000000024', 'd0000000-0000-4000-8000-000000000009', 'a0000000-0000-4000-8000-000000000016', 'Je ramène quoi à manger ?', '2026-04-01 11:00:00'),
('e0000000-0000-4000-8000-000000000025', 'd0000000-0000-4000-8000-000000000009', 'a0000000-0000-4000-8000-000000000014', 'Sandwichs et eau en quantité, le sentier fait 12 km !', '2026-04-01 11:30:00'),
-- Atelier Pâtes Fraîches
('e0000000-0000-4000-8000-000000000026', 'd0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000018', 'Buongiorno ! Bienvenue dans l''atelier, hâte de cuisiner avec vous !', '2026-04-01 18:00:00'),
('e0000000-0000-4000-8000-000000000027', 'd0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000020', 'Trop hâte chef !', '2026-04-01 18:30:00'),
('e0000000-0000-4000-8000-000000000028', 'd0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000021', 'Est-ce qu''on doit ramener nos propres tabliers ?', '2026-04-02 10:00:00'),
('e0000000-0000-4000-8000-000000000029', 'd0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000018', 'Non Chloé, je m''occupe de tout, venez juste avec votre bonne humeur !', '2026-04-02 10:15:00'),
-- Paris Secret
('e0000000-0000-4000-8000-000000000030', 'd0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000019', 'Bonjour ! Le départ se fera à la sortie du métro Saint-Paul à 14h.', '2026-04-02 09:00:00'),
('e0000000-0000-4000-8000-000000000031', 'd0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000017', 'C''est bien noté Marie, merci !', '2026-04-02 09:30:00'),
('e0000000-0000-4000-8000-000000000032', 'd0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000020', 'On passera par le Marais ?', '2026-04-02 10:00:00'),
('e0000000-0000-4000-8000-000000000033', 'd0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000019', 'Oui, et aussi par le quartier des Templiers, peu connu du grand public !', '2026-04-02 10:20:00'),
-- Balade toits de Paris
('e0000000-0000-4000-8000-000000000034', 'd0000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000006', 'Hello ! Rendez-vous au pied de l''immeuble haussmannien rue de Rivoli à 17h.', '2026-04-06 09:00:00'),
('e0000000-0000-4000-8000-000000000035', 'd0000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000003', 'C''est légal cette balade ?', '2026-04-06 09:30:00'),
('e0000000-0000-4000-8000-000000000036', 'd0000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000006', 'Tout à fait, c''est une visite avec autorisation préfectorale !', '2026-04-06 10:00:00'),
-- VTT Rambouillet
('e0000000-0000-4000-8000-000000000037', 'd0000000-0000-4000-8000-000000000015', 'a0000000-0000-4000-8000-000000000001', 'Salut les VTTistes ! RDV parking de la maison du parc à 9h. Niveau intermédiaire.', '2026-04-11 08:00:00'),
('e0000000-0000-4000-8000-000000000038', 'd0000000-0000-4000-8000-000000000015', 'a0000000-0000-4000-8000-000000000002', 'Est-ce qu''on peut louer un VTT sur place ?', '2026-04-11 08:30:00'),
('e0000000-0000-4000-8000-000000000039', 'd0000000-0000-4000-8000-000000000015', 'a0000000-0000-4000-8000-000000000001', 'Oui, location dispo au parking pour 25€ la journée.', '2026-04-11 09:00:00'),
-- Kayak mer Bretagne
('e0000000-0000-4000-8000-000000000040', 'd0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000009', 'Bienvenue ! RDV port de Quiberon à 8h30. Combinaisons fournies.', '2026-04-16 07:00:00'),
('e0000000-0000-4000-8000-000000000041', 'd0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000003', 'La météo a l''air bonne pour ce jour-là !', '2026-04-16 07:30:00'),
('e0000000-0000-4000-8000-000000000042', 'd0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000008', 'On verra des dauphins peut-être ? 😍', '2026-04-16 08:00:00'),
('e0000000-0000-4000-8000-000000000043', 'd0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000009', 'C''est possible en cette saison, croisons les doigts !', '2026-04-16 08:15:00'),
-- Atelier Crêpes
('e0000000-0000-4000-8000-000000000044', 'd0000000-0000-4000-8000-000000000017', 'a0000000-0000-4000-8000-000000000004', 'Coucou ! Atelier crêpes & cidre à 15h chez moi à Rennes. Adresse en MP.', '2026-04-21 10:00:00'),
('e0000000-0000-4000-8000-000000000045', 'd0000000-0000-4000-8000-000000000017', 'a0000000-0000-4000-8000-000000000021', 'Trop bien ! Je suis fan de crêpes au caramel beurre salé.', '2026-04-21 10:30:00'),
('e0000000-0000-4000-8000-000000000046', 'd0000000-0000-4000-8000-000000000017', 'a0000000-0000-4000-8000-000000000004', 'On en fait justement, tu vas adorer !', '2026-04-21 11:00:00'),
-- Surf Étretat
('e0000000-0000-4000-8000-000000000047', 'd0000000-0000-4000-8000-000000000018', 'a0000000-0000-4000-8000-000000000007', 'Yo ! Rendez-vous à l''école de surf d''Étretat à 10h. Planches fournies.', '2026-05-02 09:00:00'),
('e0000000-0000-4000-8000-000000000048', 'd0000000-0000-4000-8000-000000000018', 'a0000000-0000-4000-8000-000000000011', 'C''est mon premier cours de surf, des conseils ?', '2026-05-02 09:30:00'),
('e0000000-0000-4000-8000-000000000049', 'd0000000-0000-4000-8000-000000000018', 'a0000000-0000-4000-8000-000000000007', 'Détends les épaules et plie bien les genoux. Et surtout profite !', '2026-05-02 10:00:00'),
-- Marché Noël Strasbourg
('e0000000-0000-4000-8000-000000000050', 'd0000000-0000-4000-8000-000000000019', 'a0000000-0000-4000-8000-000000000005', 'Bienvenue ! RDV devant la cathédrale de Strasbourg à 14h. Couvrez-vous bien !', '2026-05-11 08:00:00'),
('e0000000-0000-4000-8000-000000000051', 'd0000000-0000-4000-8000-000000000019', 'a0000000-0000-4000-8000-000000000012', 'Il y aura du vin chaud j''espère ?', '2026-05-11 08:30:00'),
('e0000000-0000-4000-8000-000000000052', 'd0000000-0000-4000-8000-000000000019', 'a0000000-0000-4000-8000-000000000005', 'Bien sûr, et du Bretzel et des Bredele aussi !', '2026-05-11 09:00:00'),
-- Plongée Nice
('e0000000-0000-4000-8000-000000000053', 'd0000000-0000-4000-8000-000000000020', 'a0000000-0000-4000-8000-000000000017', 'Bonjour à tous ! RDV au club de plongée port Lympia à 9h. Pas besoin de certification.', '2026-05-16 08:00:00'),
('e0000000-0000-4000-8000-000000000054', 'd0000000-0000-4000-8000-000000000020', 'a0000000-0000-4000-8000-000000000004', 'On verra quoi sous l''eau ?', '2026-05-16 08:30:00'),
('e0000000-0000-4000-8000-000000000055', 'd0000000-0000-4000-8000-000000000020', 'a0000000-0000-4000-8000-000000000017', 'Des mérous, sars et si on a de la chance des pieuvres. La visibilité est excellente en septembre.', '2026-05-16 09:00:00'),
('e0000000-0000-4000-8000-000000000056', 'd0000000-0000-4000-8000-000000000020', 'a0000000-0000-4000-8000-000000000010', 'J''ai hâte, je prends mon appareil photo étanche !', '2026-05-16 09:15:00'),
-- Privés
('e0000000-0000-4000-8000-000000000057', 'd0000000-0000-4000-8000-000000000012', 'a0000000-0000-4000-8000-000000000016', 'Sarah, tu as tes chaussures de rando ?', '2026-04-02 16:00:00'),
('e0000000-0000-4000-8000-000000000058', 'd0000000-0000-4000-8000-000000000012', 'a0000000-0000-4000-8000-000000000015', 'Yes, fin prête !', '2026-04-02 16:15:00'),
('e0000000-0000-4000-8000-000000000059', 'd0000000-0000-4000-8000-000000000013', 'a0000000-0000-4000-8000-000000000020', 'Salut Chloé, hâte de l''atelier de Luigi !', '2026-04-02 19:00:00'),
('e0000000-0000-4000-8000-000000000060', 'd0000000-0000-4000-8000-000000000013', 'a0000000-0000-4000-8000-000000000021', 'Moi aussi, je m''entraîne sur la farine d''ici là haha.', '2026-04-03 01:00:00');
